import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveInputStream_getNextTarEntry_TriageGen2Test {

    /**
     * Helper to create a minimal valid Tar header (512 bytes)
     * This is a simplified mock-like approach using real bytes for a tar structure
     */
    private byte[] createTarHeader(String name, long size) {
        byte[] header = new byte[512];
        byte[] nameBytes = name.getBytes();
        System.arraycopy(nameBytes, 0, header, 0, Math.min(nameBytes.length, 100));

        // Size is at offset 124 in tar header (octal string)
        String sizeStr = Long.toOctalString(size);
        byte[] sizeBytes = sizeStr.getBytes();
        for (int i = 0; i < sizeBytes.length && (124 + i) < 512; i++) {
            header[124 + i] = sizeBytes[i];
        }
        return header;
    }



    @Test
    public void testGetNextTarEntry_SingleEntry() throws IOException {
        String name = "test.txt";
        long size = 5;
        byte[] header = createTarHeader(name, size);
        byte[] content = "hello".getBytes();

        ByteBuffer buffer = ByteBuffer.allocate(header.length + content.length);
        buffer.put(header);
        buffer.put(content);

        TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(buffer.array()));

        TarArchiveEntry entry = tais.getNextTarEntry();
        Assert.assertNotNull(entry);
        Assert.assertEquals(name, entry.getName());
        Assert.assertEquals(size, entry.getSize());

        // Verify reading content
        byte[] readBuf = new byte[5];
        int read = tais.read(readBuf);
        Assert.assertEquals(5, read);
        Assert.assertArrayEquals("hello".getBytes(), readBuf);

        // Next call should return null (assuming EOF hit)
        Assert.assertNull(tais.getNextTarEntry());
    }








}

