    }





    @Test
    public void testGetNextTarEntry_MultipleEntriesWithSkip() throws IOException {
        byte[] h1 = createTarHeader("file1.txt", 2);
        byte[] c1 = "ab".getBytes();
        byte[] h2 = createTarHeader("file2.txt", 3);
