        // First entry
        TarArchiveEntry e1 = tais.getNextTarEntry();
        Assert.assertNotNull(e1);
        Assert.assertEquals("file1.txt", e1.getName());

        // Second entry (this triggers the 'if (currEntry != null)' block to skip c1)
        TarArchiveEntry e2 = tais.getNextTarEntry();
        Assert.assertNotNull(e2);
        Assert.assertEquals("file2.txt", e2.getName());

        byte[] readBuf = new byte[3];
        tais.read(readBuf);
        Assert.assertArrayEquals("cde".getBytes(), readBuf);
    }






}

