import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveInputStream_getNextTarEntry_TriageGen2Test {

    /**
     * Helper to create a minimal valid Tar header (512 bytes)
     * This is a simplified mock-like approach using real bytes for a tar structure
     */
    private byte[] createTarHeader(String name, long size) {
        byte[] header = new byte[512];
        byte[] nameBytes = name.getBytes();
        System.arraycopy(nameBytes, 0, header, 0, Math.min(nameBytes.length, 100));

        // Size is at offset 124 in tar header (octal string)
        String sizeStr = Long.toOctalString(size);
        byte[] sizeBytes = sizeStr.getBytes();
        for (int i = 0; i < sizeBytes.length && (124 + i) < 512; i++) {
            header[124 + i] = sizeBytes[i];
        }
        return header;
    }







    @Test(expected = RuntimeException.class)
    public void testGetNextTarEntry_SkipFailure() throws IOException {
        // Create a stream that reports a large size but ends abruptly to force skip failure
        byte[] header = createTarHeader("fail.txt", 1000);
        // Providing only 10 bytes of content
        byte[] content = new byte[10];

        ByteBuffer buffer = ByteBuffer.allocate(header.length + content.length);
        buffer.put(header).put(content);

        // We need a custom InputStream that returns 0 on skip to trigger the RuntimeException
        InputStream failingSkipIs = new InputStream() {
            private final InputStream realIs = new ByteArrayInputStream(buffer.array());
            @Override
            public int read() throws IOException { return realIs.read(); }
            @Override
            public long skip(long n) throws IOException { return 0; } // Force failure
            @Override
            public int available() throws IOException { return realIs.available(); }
        };

        TarArchiveInputStream tais = new TarArchiveInputStream(failingSkipIs);
        tais.getNextTarEntry(); // First entry
        tais.getNextTarEntry(); // Second entry should trigger skip failure
    }




}

